use std::{fs,path::{Path,PathBuf},collections::{BTreeMap,BTreeSet},os::unix::fs::MetadataExt};use serde_json::{Value,json};use sha2::{Sha256,Digest};
const R:&str="/home/ubuntu/src/zopro-perf-work/group-probe218";const P:&str="/home/ubuntu/src/zopro-perf-work/group-profile216";const SEED:&str="/home/ubuntu/src/zopro-perf-work/group-stack217/proof-sha256-after-audit.json";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(p:impl AsRef<Path>,v:Value){assert!(!p.as_ref().exists());fs::write(p,serde_json::to_vec_pretty(&v).unwrap()).unwrap()}
fn median(mut v:Vec<f64>)->f64{assert!(!v.is_empty());v.sort_by(f64::total_cmp);if v.len()%2==1{v[v.len()/2]}else{(v[v.len()/2-1]+v[v.len()/2])/2.}}
fn verify(j:&Value)->Value{let pd=Path::new(j["proof_dir"].as_str().unwrap());json!({"kind":"command","name":format!("verify-{}",j["name"].as_str().unwrap()),"argv":[format!("{P}/bin/verify"),j["image"],j["image_sha256"],pd.join("0.proof"),pd.join("0.public"),j["public_sha256"]],"timeout_seconds":300})}
fn prepare(){let r=Path::new(R);fs::create_dir(r.join("bin")).unwrap();let sdk=r.join("build-run/candidate-sdk");let mut backings=vec![];for i in 0..3{let p=r.join(format!("bin/sdk{i}"));fs::copy(&sdk,&p).unwrap();let m=fs::metadata(&p).unwrap();backings.push(json!({"path":p,"sha256":hash(&p),"dev":m.dev(),"ino":m.ino()}));}save(r.join("backings.json"),json!(backings));let cfg=read(format!("{P}/jobs.json"));let c=cfg.as_array().unwrap().iter().find(|j|j["smoke"]==false&&j["boolean"]==false&&j["sampled"]==false&&j["block"]==0).unwrap();let oldplan=read(format!("{P}/main-plan.json"));let env=oldplan["steps"].as_array().unwrap().iter().find(|s|s["name"]==c["name"]).unwrap()["environment"].clone();let request="/home/ubuntu/src/zopro-perf-work/accepted-c7a201/bundle/requests/1x2.json";let mut jobs=vec![];let mut smokes=vec![];let mut mains=vec![];
let mut add=|mode:&str,block:usize,smoke:bool|{let w=if smoke{4}else{32};let n=if smoke{1}else{251};let name=format!("{}-{mode}-block{block}",if smoke{"smoke"}else{"main"});let mut env=env.clone();env["RAYON_NUM_THREADS"]=json!(w.to_string());env["ZOPRO_CPU_GROUP_PROBE"]=json!(mode);let binary=r.join(format!("bin/sdk{block}"));let pd=r.join("proofs").join(&name);let j=json!({"name":name,"mode":mode,"smoke":smoke,"block":block,"rounds":n,"workers":w,"binary":binary,"proof_dir":pd,"image":c["image"],"image_sha256":c["image_sha256"],"public_sha256":c["public_sha256"]});let mut argv=vec!["/usr/bin/sudo".to_string(),"-n".into(),"/usr/bin/env".into()];for(k,v)in env.as_object().unwrap(){argv.push(format!("{k}={}",v.as_str().unwrap()));}argv.extend(["/usr/bin/taskset".into(),"-c".into(),format!("0-{}",w-1),binary.display().to_string(),c["image"].as_str().unwrap().into(),request.into(),n.to_string(),pd.display().to_string()]);let s=json!({"kind":"command","name":name,"argv":argv,"environment":env,"timeout_seconds":600});if smoke{smokes.push(s);}else{mains.push(s);}jobs.push(j);};for mode in["STD","HB","RAW"]{add(mode,0,true);}for block in 0..3{let mut modes=["STD","HB","RAW"];modes.rotate_left(block);if block%2==1{modes.reverse();}for mode in modes{add(mode,block,false);}}drop(add);smokes.extend(jobs.iter().filter(|j|j["smoke"]==true).map(verify));let verifies=jobs.iter().filter(|j|j["smoke"]==false).map(verify).collect::<Vec<_>>();save(r.join("jobs.json"),json!(jobs));let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r.join("build-pins.json"))).unwrap();for f in["manage.rs","manage","review.rs","review","jobs.json","backings.json","mechanism.md"]{let p=r.join(f);pins.insert(p.display().to_string(),hash(p));}for p in[PathBuf::from(SEED),PathBuf::from(request),PathBuf::from(c["image"].as_str().unwrap()),PathBuf::from(format!("{P}/bin/verify")),PathBuf::from(format!("{P}/bin/xtask")),PathBuf::from("/usr/bin/sudo"),PathBuf::from("/usr/bin/taskset")].into_iter().chain((0..3).map(|i|r.join(format!("bin/sdk{i}")))){pins.insert(p.display().to_string(),hash(p));}assert_eq!(hash(SEED),"0f55f0927fcb0afff0f9b21e23966a1b34679157215a7c947955b7a1a2b83505");save(r.join("capture-pins.json"),json!(pins));for(label,steps)in[("smoke",smokes),("main",mains),("verify",verifies)]{save(r.join(format!("{label}-plan.json")),json!({"version":1,"source_pins":r.join("capture-pins.json"),"steps":steps}));}}
fn receipt(d:&Path)->String{let e=read(d.join("exit.json"));assert_eq!(e["returncode"],0);for s in["stdout","stderr"]{assert_eq!(hash(d.join(format!("{s}.log"))),e[format!("{s}_sha256")]);}fs::read_to_string(d.join("stdout.log")).unwrap()}
fn finish(smoke_only:bool){let r=Path::new(R);for(p,h)in read(r.join("capture-pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}for p in read(r.join("backings.json")).as_array().unwrap(){let m=fs::metadata(p["path"].as_str().unwrap()).unwrap();assert_eq!(m.dev(),p["dev"].as_u64().unwrap());assert_eq!(m.ino(),p["ino"].as_u64().unwrap());}let mut ledger:BTreeSet<String>=serde_json::from_value(read(SEED)).unwrap();assert_eq!(ledger.len(),59034);let mut rows=vec![];let mut records=0;let mut calls=0;let mut mincoverage=1f64;for j in read(r.join("jobs.json")).as_array().unwrap(){let smoke=j["smoke"]==true;if smoke_only&&!smoke{continue;}let name=j["name"].as_str().unwrap();let n=j["rounds"].as_u64().unwrap()as usize;let w=j["workers"].as_u64().unwrap();let out=receipt(&r.join(format!("{}-run/{name}",if smoke{"smoke"}else{"main"})));let verified=receipt(&r.join(format!("{}-run/verify-{name}",if smoke{"smoke"}else{"verify"})));let values=out.lines().filter_map(|l|l.strip_prefix("SAMPLE ")).map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();let phases=out.lines().filter_map(|l|l.strip_prefix("PHASE ")).map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();let summary:Value=serde_json::from_str(out.lines().find_map(|l|l.strip_prefix("SUMMARY ")).unwrap()).unwrap();assert_eq!(values.len(),n);assert_eq!(phases.len(),n);for(k,v)in[("rounds",n as u64),("priming",3),("workers",w),("generated_fast_parses",n as u64),("generated_timed_key_scans",0),("generated_timed_fixed_scans",0),("boolean_positions",0)]{assert_eq!(summary[k],v);}assert_eq!(summary["boolean_routes"],json!([0,0,0,0]));assert_eq!(summary["placement_before"],summary["placement_after"]);for(i,worker)in summary["placement_before"]["worker_rows"].as_array().unwrap().iter().enumerate(){assert_eq!(worker["allowed"],json!([i]));}let setup:Value=serde_json::from_str(out.lines().find_map(|l|l.strip_prefix("PMU_SETUP ")).unwrap()).unwrap();assert_eq!(setup["euid"],0);assert_eq!(setup["workers"],w);let mut metrics=BTreeMap::<&str,Vec<f64>>::new();for(i,(v,p))in values.iter().zip(&phases).enumerate(){assert_eq!(v["round"],i);assert_eq!(p["round"],i);let ms=v["ms"].as_f64().unwrap();assert!(ms.is_finite()&&ms>0.);let ev:Vec<u64>=serde_json::from_value(p["events"].clone()).unwrap();assert_eq!(ev.len(),24);for &k in[14,15,17,19,20].iter(){assert_eq!(ev[k],0);}for(a,b)in[(23,0),(0,1),(1,2),(2,3),(3,4),(4,5),(3,6),(6,7),(3,8),(8,10),(10,11),(11,12),(12,13),(13,9),(5,16),(7,16),(9,16),(16,18)]{assert!(ev[a]>0&&ev[b]>=ev[a]);}let c:Vec<u64>=serde_json::from_value(p["group_cpu"].clone()).unwrap();assert!(c[0]>0&&c[1]>=c[0]&&c[2]==c[3]&&(1..=w).contains(&c[2]));let pmu:Vec<u64>=serde_json::from_value(p["group_pmu"].clone()).unwrap();assert_eq!(pmu.len(),8);let d:Vec<_>=(0..4).map(|i|pmu[2*i+1].checked_sub(pmu[2*i]).unwrap()).collect();assert!(d.iter().all(|&x|x>0));let coverage=d[3]as f64/d[2]as f64;mincoverage=mincoverage.min(coverage);assert!(coverage>=0.99&&d[3]<=d[2]+1000);for(k,x)in[("group_CPU_ms",(c[1]-c[0])as f64/1e6),("group_wall_ms",(ev[11]-ev[10])as f64/1e6),("group_cycles",d[0]as f64),("group_instructions",d[1]as f64),("group_CPI",d[0]as f64/d[1]as f64),("MSM_join_ms",(ev[16]-ev[3])as f64/1e6),("A_span_ms",(ev[5]-ev[4])as f64/1e6),("G2_span_ms",(ev[9]-ev[8])as f64/1e6)]{metrics.entry(k).or_default().push(x);}records+=1;}let pd=Path::new(j["proof_dir"].as_str().unwrap());let proof=hash(pd.join("0.proof"));assert_eq!(fs::metadata(pd.join("0.proof")).unwrap().len(),164);assert_eq!(hash(pd.join("0.public")),j["public_sha256"]);assert!(verified.contains(&format!("VERIFIED proof_sha256={proof} ")));assert!(ledger.insert(proof.clone()));rows.push(json!({"job":j,"mean_ms":values.iter().map(|v|v["ms"].as_f64().unwrap()).sum::<f64>()/n as f64,"cpu_ms":(summary["user_cpu_ms"].as_f64().unwrap()+summary["system_cpu_ms"].as_f64().unwrap())/n as f64,"peak_rss_mib":summary["whole_process_maxrss_kib"].as_f64().unwrap()/1024.,"medians":metrics.into_iter().map(|(k,v)|(k,median(v))).collect::<BTreeMap<_,_>>(),"proof_sha256":proof}));calls+=n+3;}
let label=if smoke_only{"smoke"}else{"main"};save(r.join(format!("{label}-rows.json")),json!(rows));save(r.join(format!("proof-sha256-after-{label}.json")),json!(ledger));if smoke_only{assert_eq!(rows.len(),3);println!("Three smoke exports verified;all invariants PASS;ledger{}",ledger.len());return;}assert_eq!(rows.len(),12);assert_eq!(records,2262);assert_eq!(calls,2298);let get=|mode:&str,block:usize|rows.iter().find(|r|r["job"]["smoke"]==false&&r["job"]["mode"]==mode&&r["job"]["block"]==block).unwrap();let mut comparisons=vec![];let mut ready=true;for control in["STD","HB"]{let paired=(0..3).map(|b|get("RAW",b)["mean_ms"].as_f64().unwrap()/get(control,b)["mean_ms"].as_f64().unwrap()).collect::<Vec<_>>();let cpu=median((0..3).map(|b|get("RAW",b)["cpu_ms"].as_f64().unwrap()/get(control,b)["cpu_ms"].as_f64().unwrap()).collect());let rss=|m:&str|(0..3).map(|b|get(m,b)["peak_rss_mib"].as_f64().unwrap()).fold(0f64,f64::max);let ratio=median(paired.clone());let wins=paired.iter().filter(|&&v|v<1.).count();let pass=ratio<1.&&wins>=2&&cpu<=1.02&&rss("RAW")<=rss(control)*1.10+8.;ready&=pass;comparisons.push(json!({"control":control,"SDK_ratios":paired,"paired_median":ratio,"wins":wins,"cpu_ratio":cpu,"rss_RAW":rss("RAW"),"rss_control":rss(control),"pass":pass}));}let calibration=median((0..3).map(|b|get("HB",b)["mean_ms"].as_f64().unwrap()/get("STD",b)["mean_ms"].as_f64().unwrap()).collect());let calibrated=(1./1.03..=1.03).contains(&calibration);ready&=calibrated;save(r.join("result.json"),json!({"diagnostic_screen":true,"adopted":false,"ready_for_qualification":ready,"comparisons":comparisons,"HB_over_STD":calibration,"calibration_pass":calibrated,"PMU_minimum_coverage":mincoverage,"records":records,"SDK_calls":calls,"fresh_Gnark_exports":12,"canonical_count":ledger.len(),"canonical_sha256":hash(r.join("proof-sha256-after-main.json")),"rows":rows}));println!("Screen readyforqualification={ready};CPU/PMU/proofinvariants PASS;{calls}SDKcalls;ledger{}",ledger.len());}
